from common import *
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':1200,'height':800},permissions=['clipboard-read','clipboard-write']); pg=ctx.new_page()
    errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.route('**/config.js',lambda r:r.fulfill(content_type='text/javascript',body=CFG)); pg.route('**/supabase.js',lambda r:r.fulfill(content_type='text/javascript',body=STUB))
    pg.route('https://test.supabase.co/**',fn); pg.route(re.compile(r'https://fonts\..*'),lambda r:r.abort())
    pg.goto('http://localhost:8765/index.html',wait_until='domcontentloaded')
    # --- intro sequence order ---
    pg.wait_for_timeout(500); s0=pg.evaluate('({lit:LIT.filter(l=>(performance.now()-it0)/1000>l).length,r:ifw.r.length,p:ifw.p.length,appOn:document.getElementById("app").classList.contains("on")})')
    check('0-1s: dark, no diya lit, no fireworks, homepage hidden',s0['lit']==0 and s0['r']==0 and s0['p']==0 and not s0['appOn'],s0)
    pg.wait_for_timeout(2000); s1=pg.evaluate('({lit:LIT.filter(l=>(performance.now()-it0)/1000>l).length,r:ifw.r.length,p:ifw.p.length})')
    check('~2.5s: diyas lighting one by one, still no rockets or bursts',1<=s1['lit']<6 and s1['r']==0 and s1['p']==0,s1)
    pg.wait_for_timeout(1300); s2=pg.evaluate('({r:ifw.r.length})'); check('~3.8s: rockets launched upward',s2['r']>0,s2)
    pg.wait_for_timeout(2400); s3=pg.evaluate('({p:ifw.p.length,appOn:document.getElementById("app").classList.contains("on")})'); check('~6.2s: fireworks bursting, homepage not yet shown',s3['p']>0 and not s3['appOn'],s3)
    pg.wait_for_timeout(2300); check('~8.5s: homepage revealed',pg.evaluate('document.getElementById("app").classList.contains("on")'))
