    check('background fireworks canvas is drawing',pg.evaluate('bgRun&&(bfw.p.length+bfw.r.length>=0)&&bgOn'))
    check('intro overlay removed',pg.evaluate('document.getElementById("intro").hidden'))
    # skip + replay
    pg.click('#replay'); pg.wait_for_timeout(300); check('replay restarts intro',pg.evaluate('irun&&!revealed'))
    pg.click('#skip'); pg.wait_for_timeout(300); check('skip reveals homepage',pg.evaluate('revealed'))
