    # --- greeting card + privacy sentinel ---
    pg.goto('about:blank'); pg.goto('http://localhost:8765/index.html#wishes',wait_until='domcontentloaded'); pg.click('#skip'); pg.wait_for_timeout(500)
    pg.fill('#to','ZzRecipientQ'); pg.fill('#from','ZzSenderQ'); pg.fill('#msg','ZzMessageQ wishes'); pg.click('#themes button:nth-child(3)')
