    check('greeting PNG downloads',d.value.suggested_filename.endswith('.png'))
    pg.click('#cp'); check('greeting copy works',pg.evaluate('navigator.clipboard.readText()').count('ZzRecipientQ')==1)
    # --- gallery + report ---
    pg.evaluate("location.hash='#gallery'"); pg.wait_for_selector('#gal .ph'); check('gallery renders photos from the API',pg.locator('#gal .ph').count()==6)
    pg.click('[data-rp]'); pg.select_option('#rreason','spam'); pg.click('#rsend'); pg.wait_for_timeout(300)
    check('report sent with reason',state['reports']==[{'photo_id':'22222222-2222-4222-8222-222222222220','reason':'spam','details':''}],state['reports'])
    # --- upload ---
    open('/tmp/p.png','wb').write(PNG); pg.set_input_files('#pick','/tmp/p.png'); pg.wait_for_selector('#pv:not([hidden])')
    pg.click('#upgo'); check('upload needs consent',('permission' in pg.inner_text('#ups')))
    pg.check('#consent'); pg.click('#upgo'); pg.wait_for_timeout(500)
    check('upload success message',pg.inner_text('#ups').startswith('Your beautiful Diwali memory has been submitted! Thank you for spreading happiness.'))
    up=[r for r in R if r[0]=='upload-photo' and r[1]=='POST']; check('upload sent as JPEG blob',len(up)==1 and 'image/jpeg' in up[0][2] if up else False)
    pg.set_input_files('#pick',files=[{'name':'a.gif','mimeType':'image/gif','buffer':b'GIF89a'}]); check('wrong file type rejected client-side',('JPG, PNG or WebP' in pg.inner_text('#ups')))
    # --- tickets ---
    pg.evaluate("location.hash='#support'"); pg.wait_for_selector('#tkf')
    pg.click('#tkgo'); check('ticket: category required',('category' in pg.inner_text('#tks')))
    pg.select_option('#tkcat','greeting_card'); pg.fill('#tktitle','ab'); pg.click('#tkgo'); check('ticket: short title rejected',('title' in pg.inner_text('#tks')))
    pg.fill('#tktitle','Card will not download'); pg.fill('#tkdesc','short'); pg.click('#tkgo'); check('ticket: short description rejected',('describe' in pg.inner_text('#tks')))
    pg.fill('#tkdesc','The PNG download button does nothing on my phone.'); pg.fill('#tkemail','bad'); pg.click('#tkgo'); check('ticket: bad email rejected',('email' in pg.inner_text('#tks')))
    pg.fill('#tkemail',''); pg.set_input_files('#tkfile',files=[{'name':'a.gif','mimeType':'image/gif','buffer':b'GIF89a'}]); pg.click('#tkgo'); check('ticket: bad attachment type rejected',('screenshot' in pg.inner_text('#tks')))
    pg.set_input_files('#tkfile','/tmp/p.png'); pg.click('#tkgo'); pg.wait_for_function("document.getElementById('tks').innerText.includes('Tracking code')",timeout=8000)
    msg=pg.inner_text('#tks'); check('ticket: ID shown (DIWALI-YYYY-NNNN) with tracking code',bool(re.search(r'DIWALI-2026-0001',msg)) and 'Tracking code' in msg,msg)
    pg.fill('#tktitle','Second ticket'); pg.select_option('#tkcat','gallery'); pg.fill('#tkdesc','Gallery is slow to load for me today.'); pg.click('#tkgo'); pg.wait_for_timeout(400)
    check('ticket IDs are unique and sequential',len({t['ticket_no'] for t in state['tickets']})==2 and state['tickets'][1]['ticket_no']=='DIWALI-2026-0002')
