    pg.fill('#trcode','wrong'+'x'*20); pg.click('#trf button'); pg.wait_for_timeout(300); check('tracking with wrong code refused',('incorrect' in pg.inner_text('#trs')))
    pg.fill('#trno',t1['ticket_no']); pg.fill('#trcode',''); pg.click('#trf button'); pg.wait_for_timeout(300); check('tracking ID alone (no code) refused',('incorrect' in pg.inner_text('#trs')))
