    pg.evaluate("location.hash='#admin'"); pg.wait_for_selector('#adlogin')
    check('admin dashboard hidden before login',pg.is_hidden('#addash'))
    pg.fill('#ademail','a@b.co'); pg.fill('#adpass','badpass'); pg.click('#adlogin button'); pg.wait_for_timeout(300); check('bad admin login refused',('failed' in pg.inner_text('#adst')) and pg.is_hidden('#addash'))
    check('unauthenticated admin API call refused (mock enforces token)',pg.evaluate("fetch('https://test.supabase.co/functions/v1/admin',{method:'POST',body:JSON.stringify({action:'stats'})}).then(r=>r.status)")==401)
    pg.fill('#adpass','goodpass'); pg.click('#adlogin button'); pg.wait_for_selector('#addash:not([hidden])'); pg.wait_for_selector('#adlist .ph')
    check('admin sees pending photo + stats incl. tickets',('Active tickets 2' in pg.inner_text('#adstats')))
    pg.click('[data-act=approved]'); pg.wait_for_timeout(400); check('photo approve works',state['photos'][0]['status']=='approved')
    pg.click('[data-t=tickets]'); pg.wait_for_selector('#tlist .tk'); check('admin ticket list shows both tickets + attachment link',pg.locator('#tlist .tk').count()==2 and 'View attachment' in pg.inner_text('#tlist'))
    pg.fill('#tq','0002'); pg.click('#tgo'); pg.wait_for_timeout(400); check('search by ticket ID',pg.locator('#tlist .tk').count()==1 and 'DIWALI-2026-0002' in pg.inner_text('#tlist'))
    pg.fill('#tq',''); pg.select_option('#tcat','greeting_card'); pg.click('#tgo'); pg.wait_for_timeout(400); check('filter by category',pg.locator('#tlist .tk').count()==1 and 'DIWALI-2026-0001' in pg.inner_text('#tlist'))
    pg.select_option('#tcat',''); pg.click('#tgo'); pg.wait_for_timeout(300)
    card=pg.locator('#tlist .tk').first; card.locator('[data-f=status]').select_option('resolved'); card.locator('[data-f=notes]').fill('Checked, fixed.'); card.locator('[data-tsave]').click(); pg.wait_for_timeout(500)
    check('status + internal note saved',state['tickets'][0]['status']=='resolved' and state['tickets'][0]['admin_notes']=='Checked, fixed.',state['tickets'][0]['status'])
    pg.select_option('#tst','resolved'); pg.click('#tgo'); pg.wait_for_timeout(300); check('filter by status',pg.locator('#tlist .tk').count()==1)
    pg.once('dialog',lambda d:d.accept()); pg.locator('#tlist .tk').first.locator('[data-tdel]').click(); pg.wait_for_timeout(500); check('delete ticket',len(state['tickets'])==1)
    pg.evaluate("location.hash='#support'"); pg.fill('#trno',t1['ticket_no']); pg.fill('#trcode',t1['code']); pg.click('#trf button'); pg.wait_for_timeout(300); check('deleted ticket no longer trackable',('incorrect' in pg.inner_text('#trs')))
    pg.click('#adtabs button') if False else None
    # --- privacy: greeting sentinels never left the browser ---
    leaked=[r for r in R if any(s in r[2] for s in ('ZzRecipientQ','ZzSenderQ','ZzMessageQ'))]
    store=pg.evaluate('JSON.stringify(localStorage)+JSON.stringify(sessionStorage)')
    check('analytics requests carry only an event name',all(set(x)=={'event'} for x in state['events']) and len(state['events'])>0,state['events'])
    check('greeting names/message never sent to backend (%d requests checked)'%len(R),not leaked and not any(s in store for s in ('ZzRecipientQ','ZzSenderQ','ZzMessageQ')),leaked)
    check('ticket requests carry no greeting fields',all(not any(k in t['_fields'] for k in ('to','from','msg','recipient','sender')) for t in state['tickets']))
    check('no uncaught JS errors',not errs,errs)
    # --- mobile overflow ---
    m=b.new_context(viewport={'width':375,'height':800}); mp=m.new_page()
    mp.route('**/config.js',lambda r:r.fulfill(content_type='text/javascript',body=CFG)); mp.route('**/supabase.js',lambda r:r.fulfill(content_type='text/javascript',body=STUB)); mp.route('https://test.supabase.co/**',fn); mp.route(re.compile(r'https://fonts\..*'),lambda r:r.abort())
    mp.goto('http://localhost:8765/index.html',wait_until='domcontentloaded'); mp.click('#skip'); mp.wait_for_timeout(500)
